//! iTerm2 inline image visual pilot — animated GIF first-frame golden.
//!
//! Catalog row: `ITERM2-1337-FILE-ANIMATED-GIF`
//! Apex: `GoldenImage`
//!
//! Drives `OSC 1337 ; File=inline=1:<16x16-3-frame-gif-b64> ST` through
//! every visual rung. A multi-frame GIF routes through `decode_gif_frames`
//! → `ImageCache::store_animated`; the golden captures the static first
//! frame (rung 8 renders frame 0 — animation advancement is pinned
//! separately at the state level by
//! `iterm2_animated_gif_advance_animations_drives_frame_transitions`).
//! Pairs with the state-snapshot pin
//! `osc1337_file_multi_frame_gif_stores_animated` per the §14.4 dual-gate.

use super::iterm2_gif_pilot::run_gif_rung8_pilot;

/// `OSC 1337 ; File=inline=1:<b64> ST` with the b64 of a 16×16 3-frame
/// animated GIF produced by the `image` crate (100ms per frame, infinite
/// loop). The handler promotes it via `store_animated`; the golden
/// captures the first frame. The `expected_animated_frames: Some(3)` arg
/// pins (via `assert_payload_decodes`) that this payload genuinely carries
/// 3 frames — distinguishing the animated path from the single-frame
/// fall-through, so the const cannot silently drift to a 1-frame GIF.
const ITERM2_ANIMATED_GIF_BYTES: &[u8] = b"\x1b]1337;File=inline=1:\x1b\\";

/// Drives a 3-frame animated GIF OSC payload through every visual rung
/// and captures the first-frame golden. `expected_animated_frames: Some(3)`
/// pins (via the shared driver's decode-guard) that the payload promotes
/// through `store_animated` with 3 frames. Catalog row
/// `ITERM2-1337-FILE-ANIMATED-GIF`.
#[test]
fn iterm2_image_animated_gif_first_frame_drives_every_rung_green() {
    run_gif_rung8_pilot(
        "ITERM2-1337-FILE-ANIMATED-GIF",
        ITERM2_ANIMATED_GIF_BYTES,
        "iterm2_image_animated_gif_first_frame",
        Some(3),
    );
}
